# One line of a place's starter conversation, shown on the place page before any visit.
# Generated by PlacePhraseGenerator (via PlacePhrasesJob); shared by all users.
class PlacePhrase < ApplicationRecord
  belongs_to :place

  # The flow from walking in to walking out; every place's set covers each stage
  enum :stage, { arriving: 0, ordering: 1, details: 2, paying: 3, leaving: 4 }
  enum :speaker, { customer: 0, staff: 1 }

  STAGE_LABELS = {
    "arriving" => "Arriving", "ordering" => "Ordering", "details" => "Choosing options",
    "paying" => "Paying", "leaving" => "Leaving"
  }.freeze

  validates :position, presence: true, uniqueness: { scope: :place_id }
  validates :japanese, :romaji, :english, presence: true, length: { maximum: 200 }
end
